        {
            SAL_WARN("jvmfwk.javaenvsetup", "javaldx failed!");
            return -1;
        }

        if (!aInfo)
        {
            if (!findAndSelect(&aInfo))
                return -1;
        }
        else
        {
            //check if the JRE was not uninstalled
            bool bExist = false;
            errcode = jfw_existJRE(aInfo.get(), &bExist);
            if (errcode == JFW_E_NONE)
            {
                if (!bExist && !findAndSelect(&aInfo))
                    return -1;
            }
